import{_ as r,H as o,f as t,i as s}from"./chunks/framework.DLd0CbzH.js";const m=JSON.parse('{"title":"Что реализовано и что ожидать","description":"Текущий статус проекта OmniCraft ERP и дорожная карта развития (Roadmap).","frontmatter":{"title":"Что реализовано и что ожидать","description":"Текущий статус проекта OmniCraft ERP и дорожная карта развития (Roadmap).","order":4},"headers":[],"relativePath":"ru/docs/roadmap.md","filePath":"ru/docs/roadmap.md"}'),e={name:"ru/docs/roadmap.md"};function l(i,a,n,d,p,c){return o(),t("div",null,[...a[0]||(a[0]=[s('<div class="warning custom-block"><p class="custom-block-title">📌 Документация находится в разработке</p><p><strong>Уважаемые пользователи!</strong></p><p>Поскольку OmniCraft ERP сейчас находится в стадии активной бета-версии, регулярно дорабатывается и расширяется, справочные материалы также обновляются постепенно.</p><p>На данный момент воспринимайте документацию как ориентировочную — она является неполной, может временно не содержать описание некоторых функций или содержать неточности.</p></div><h1 id="🚀-что-реализовано-и-что-ожидать" tabindex="-1">🚀 Что реализовано и что ожидать <a class="header-anchor" href="#🚀-что-реализовано-и-что-ожидать" aria-label="Permalink to &quot;🚀 Что реализовано и что ожидать&quot;">​</a></h1><p>OmniCraft ERP — это активно развивающийся продукт. Мы регулярно выпускаем обновления, опираясь на собственную практику в ремесле и отзывы пользователей. На этой странице вы можете узнать, что уже стабильно работает, а какие функции находятся в разработке.</p><h2 id="✅-текущии-статус-стабильное-ядро-версия-1-0-x" tabindex="-1">✅ Текущий статус: Стабильное ядро (Версия 1.0.x) <a class="header-anchor" href="#✅-текущии-статус-стабильное-ядро-версия-1-0-x" aria-label="Permalink to &quot;✅ Текущий статус: Стабильное ядро (Версия 1.0.x)&quot;">​</a></h2><p>На данный момент полностью реализован и отлажен <strong>Основной производственный конвейер</strong>. Базовая версия программы позволяет вести полноценный управленческий учет микропредприятия:</p><ul><li><strong>Имущество:</strong> Умная амортизация оборудования и расчет остаточной стоимости мастерской.</li><li><strong>Склад (MAC):</strong> Партионный учет сырья с распределением стоимости доставки на себестоимость материалов без искажений.</li><li><strong>Калькулятор:</strong> Конструктор рецептов с учетом труда мастера и накладных расходов.</li><li><strong>Производство:</strong> Динамический верстак с умным каскадным пересчетом резервов сырья (очередь FIFO).</li><li><strong>Сбыт:</strong> Управление каналами продаж, наценками и POS-терминал с учетом стоимости логистики (оплачивает клиент или мастерская).</li><li><strong>Финансы:</strong> Глобальный управленческий баланс (Капитал), кассовая книга (ДДС) и продвинутая графическая аналитика (Финансовый пульс, Точка безубыточности).</li><li><strong>Безопасность:</strong> Встроены ротационные GFS-бэкапы, режим журналирования базы данных WAL и защита от потери информации при сбоях питания.</li></ul><p>Все эти функции доступны в рамках <a href="./licenses">Базовой (Standard) лицензии</a>.</p><hr><h2 id="🔮-в-разработке-pro-режим-и-экосистема-roadmap" tabindex="-1">🔮 В разработке: PRO-режим и Экосистема (Roadmap) <a class="header-anchor" href="#🔮-в-разработке-pro-режим-и-экосистема-roadmap" aria-label="Permalink to &quot;🔮 В разработке: PRO-режим и Экосистема (Roadmap)&quot;">​</a></h2><p>Мы уже заложили фундаментальную архитектуру для следующих крупных обновлений, которые войдут в <strong>PRO-лицензию</strong>.</p><h3 id="_1-мультипространства-multi-workspaces" tabindex="-1">1. Мультипространства (Multi-Workspaces) <a class="header-anchor" href="#_1-мультипространства-multi-workspaces" aria-label="Permalink to &quot;1. Мультипространства (Multi-Workspaces)&quot;">​</a></h3><p>Возможность создавать внутри одной программы независимые базы данных.</p><ul><li><em>Зачем это нужно?</em> Если у вас несколько разных направлений (например, кожевенная мастерская и продажа инфопродуктов/выкроек), вы сможете вести их в изолированных пространствах с разными валютами, наценками и складами, мгновенно переключаясь между ними через боковое меню.</li></ul><h3 id="_2-глобальная-вкладка-«мои-капитал»-личные-финансы" tabindex="-1">2. Глобальная вкладка «Мой капитал» (Личные финансы) <a class="header-anchor" href="#_2-глобальная-вкладка-«мои-капитал»-личные-финансы" aria-label="Permalink to &quot;2. Глобальная вкладка «Мой капитал» (Личные финансы)&quot;">​</a></h3><p>Революционный подход к учету личных денег без рутины.</p><ul><li>Вы будете просто вносить остатки по своим банковским картам и крупным активам вне бизнеса (квартира, машина).</li><li>Программа сама консолидирует чистую прибыль со всех ваших рабочих пространств, сравнит её с реальным ростом вашего капитала на счетах и <strong>автоматически вычислит ваши повседневные траты на жизнь</strong>. Больше не нужно вписывать каждый чек за кофе или продукты в программу учета финансов.</li></ul><h3 id="_3-сквозные-тематические-модули-add-ons" tabindex="-1">3. Сквозные тематические модули (Add-ons) <a class="header-anchor" href="#_3-сквозные-тематические-модули-add-ons" aria-label="Permalink to &quot;3. Сквозные тематические модули (Add-ons)&quot;">​</a></h3><p>Нишевые инструменты, которые можно будет подключать дополнительно. Они будут работать поверх всех пространств.</p><ul><li><strong>Модуль Выкроек:</strong> Каталогизация лекал, расчет площади раскроя, привязка файлов и чертежей.</li><li><strong>Модуль Услуг:</strong> Учет времени, индивидуальных ремонтов и кастомных заказов без привязки к жесткому складу готовой продукции.</li></ul><blockquote><p><strong>Автоматические обновления</strong> Программа имеет встроенную систему проверки версий. При запуске она сама сообщит вам, если вышло обновление с новыми функциями, и предложит ссылку на скачивание. Ваши базы данных при обновлении переносятся автоматически и бесшовно.</p></blockquote>',20)])])}const h=r(e,[["render",l]]);export{m as __pageData,h as default};
